<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>AIVA/Grace - AIVA's Conversational Runtime</title>
    <style>
      :root {
        --primary: #00bfff;
        --secondary: #87ceeb;
        --background: #f8f9fa;
        --highlight: #e3f2fd;
        --text: #333;
        --border: #ddd;
        --shadow: 0 4px 6px rgba(0,0,0,0.1);
      }

      body {
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
        background-color: var(--background);
        color: var(--text);
        max-width: 1200px;
        margin: 0 auto;
        padding: 2rem;
        line-height: 1.6;
      }

      .header {
        text-align: center;
        margin-bottom: 3rem;
      }

      .header h1 {
        font-size: 2.2rem;
        color: var(--primary);
        margin-bottom: 0.5rem;
      }

      .header p {
        font-size: 1.1rem;
        color: #666;
        max-width: 800px;
        margin: 0 auto 2rem;
      }

      .controls {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 2rem;
        gap: 1rem;
      }

      .control-group {
        display: flex;
        gap: 0.5rem;
      }

      button {
        background-color: var(--primary);
        color: white;
        border: none;
        border-radius: 4px;
        padding: 0.75rem 1.5rem;
        font-weight: 600;
        cursor: pointer;
        transition: background-color 0.2s, transform 0.2s;
      }

      button:disabled {
        background-color: #666;
        cursor: not-allowed;
      }

      button:hover:not(:disabled) {
        background-color: #0099cc;
        transform: translateY(-1px);
      }

      .canvas-container {
        position: relative;
        width: 100%;
        height: 400px;
        background: white;
        border-radius: 8px;
        overflow: hidden;
        box-shadow: var(--shadow);
        margin-bottom: 2rem;
      }

      .chat-area {
        background: white;
        border-radius: 8px;
        padding: 1rem;
        box-shadow: var(--shadow);
        margin-bottom: 2rem;
      }

      .chat-message {
        padding: 0.75rem 1rem;
        border-radius: 18px;
        margin-bottom: 1rem;
      }

      .user-message {
        background-color: var(--secondary);
        margin-left: 2rem;
        max-width: 60%;
      }

      .grace-message {
        background-color: #d4e6f1;
        margin-right: 2rem;
        max-width: 60%;
      }

      .step-label {
        font-size: 1.2rem;
        font-weight: 600;
        text-align: center;
        margin-bottom: 1rem;
        color: var(--primary);
      }

      .optional-capabilities {
        margin-top: 2rem;
        padding: 1rem;
        background-color: #f0f8ff;
        border-left: 4px solid var(--primary);
      }

      .optional-capabilities h3 {
        margin-top: 0;
        color: var(--primary);
      }

      .optional-capabilities p {
        color: #666;
        font-size: 0.9rem;
      }

      svg {
        max-width: 100%;
        height: auto;
      }

      .highlight {
        background-color: var(--highlight);
        padding: 0.5rem;
        border-radius: 4px;
      }

      @media (max-width: 768px) {
        .controls {
          flex-direction: column;
          align-items: stretch;
        }

        .chat-area {
          padding: 0.5rem;
        }

        .user-message, .grace-message {
          max-width: 80%;
          margin: 0.5rem auto;
        }

        .canvas-container {
          height: 300px;
        }
      }
    </style>
  </head>
  <body>
    <div class="header">
      <h1>AIVA/Grace</h1>
      <p>AIVA's Conversational Runtime</p>
    </div>

    <div class="controls">
      <div class="control-group">
        <button id="reset">Reset</button>
        <button id="next" disabled>Next</button>
      </div>
      <div class="control-group">
        <button id="play">Play</button>
      </div>
    </div>

    <div class="step-label" id="step-label">Composing a message in the Console</div>

    <div class="canvas-container" id="canvas">
      <svg viewBox="0 0 800 400" xmlns="http://www.w3.org/2000/svg">
        <!-- Desktop and Terminal Background -->
        <rect x="100" y="100" width="600" height="250" rx="8" fill="#333" />
        <rect x="150" y="120" width="500" height="20" rx="2" fill="#555" />
        <text x="200" y="140" font-family="monospace" font-size="12" fill="#aaa">$ launch.sh</text>

        <!-- Terminal Output -->
        <text x="150" y="170" font-family="monospace" font-size="12" fill="#0f0">✓ AIVA Console ready</text>
        <text x="150" y="190" font-family="monospace" font-size="12" fill="#0f0">✓ Telepathy Service started</text>
        <text x="150" y="210" font-family="monospace" font-size="12" fill="#0f0">✓ Memory Service ready</text>
        <text x="150" y="230" font-family="monospace" font-size="12" fill="#0f0">✓ OpenAI Router ready</text>

        <!-- User Interface -->
        <rect x="100" y="20" width="600" height="80" rx="8" fill="#333" />
        <rect x="150" y="30" width="500" height="20" rx="2" fill="#555" />
        <text x="200" y="50" font-family="monospace" font-size="12" fill="#aaa">Console: AIVA/Grace Runtime</text>

        <!-- Input Box -->
        <rect x="150" y="100" width="500" height="40" rx="4" fill="#f0f0f0" stroke="#00bfff" stroke-width="1" />
        <text x="200" y="125" font-family="sans-serif" font-size="14" fill="#333">How does AIVA remember our conversation?</text>

        <!-- AIVA's Console Icon -->
        <circle cx="100" cy="100" r="30" fill="#00bfff" />
        <circle cx="90" cy="90" r="4" fill="#00bfff" />
        <circle cx="110" cy="90" r="4" fill="#00bfff" />
        <circle cx="100" cy="110" r="4" fill="#00bfff" />
        <text x="60" y="120" font-family="sans-serif" font-size="10" fill="white">Console</text>

        <!-- User Avatar -->
        <circle cx="700" cy="350" r="30" fill="#ff9999" />
        <text x="710" y="360" font-family="sans-serif" font-size="10" fill="#333">You</text>
      </svg>
    </div>

    <div class="chat-area">
      <div class="user-message">
        How does AIVA remember our conversation?
      </div>
    </div>

    <div class="optional-capabilities">
      <h3>Optional Capabilities</h3>
      <p>Canvas, Imaging and MOSS are available as add-on services. These are not part of the core telepathy path.</p>
    </div>

    <script>
      // State management
      const state = {
        step: 0,
        playing: false,
        interval: null
      };

      // DOM elements
      const stepLabel = document.getElementById('step-label');
      const nextButton = document.getElementById('next');
      const resetButton = document.getElementById('reset');
      const playButton = document.getElementById('play');
      const canvas = document.getElementById('canvas');

      // SVG elements
      const svg = canvas.querySelector('svg');
      const envelope = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      envelope.setAttribute('d', 'M150,180 Q300,150 450,180 Q500,210 500,210');
      envelope.setAttribute('stroke', '#ff9999');
      envelope.setAttribute('stroke-width', '2');
      envelope.setAttribute('fill', 'none');
      envelope.style.opacity = '0';

      const grace = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      grace.setAttribute('cx', '650');
      grace.setAttribute('cy', '100');
      grace.setAttribute('r', '25');
      grace.setAttribute('fill', '#a7eaff');
      grace.setAttribute('stroke', '#00bfff');
      grace.setAttribute('stroke-width', '2');
      grace.style.opacity = '0';

      const textBubble = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      textBubble.setAttribute('d', 'M650,90 Q700,80 750,90 Q800,100 800,100');
      textBubble.setAttribute('stroke', '#00bfff');
      textBubble.setAttribute('stroke-width', '1');
      textBubble.setAttribute('fill', 'none');
      textBubble.style.opacity = '0';

      // Add elements to SVG
      svg.appendChild(envelope);
      svg.appendChild(grace);
      svg.appendChild(textBubble);

      // Add Grace's text
      const graceText = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      graceText.setAttribute('x', '660');
      graceText.setAttribute('y', '110');
      graceText.setAttribute('font-family', 'sans-serif');
      graceText.setAttribute('font-size', '14');
      graceText.setAttribute('fill', '#333');
      graceText.textContent = 'AIVA maintains your conversation history in its memory. It keeps your recent exchanges and uses them to personalize our interaction.';
      graceText.style.opacity = '0';

      svg.appendChild(graceText);

      // Update SVG based on state
      function updateSVG() {
        if (state.step === 0) {
          svg.removeChild(envelope);
          svg.removeChild(grace);
          svg.removeChild(textBubble);
          svg.removeChild(graceText);

          // Re-add just the terminal
          svg.innerHTML = `
            <rect x="100" y="100" width="600" height="250" rx="8" fill="#333" />
            <rect x="150" y="120" width="500" height="20" rx="2" fill="#555" />
            <text x="200" y="140" font-family="monospace" font-size="12" fill="#aaa">$ launch.sh</text>
            <text x="150" y="170" font-family="monospace" font-size="12" fill="#0f0">✓ AIVA Console ready</text>
            <text x="150" y="190" font-family="monospace" font-size="12" fill="#0f0">✓ Telepathy Service started</text>
            <text x="150" y="210" font-family="monospace" font-size="12" fill="#0f0">✓ Memory Service ready</text>
            <text x="150" y="230" font-family="monospace" font-size="12" fill="#0f0">✓ OpenAI Router ready</text>
            <rect x="100" y="20" width="600" height="80" rx="8" fill="#333" />
            <rect x="150" y="30" width="500" height="20" rx="2" fill="#555" />
            <text x="200" y="50" font-family="monospace" font-size="12" fill="#aaa">Console: AIVA/Grace Runtime</text>
            <rect x="150" y="100" width="500" height="40" rx="4" fill="#f0f0f0" stroke="#00bfff" stroke-width="1" />
            <text x="200" y="125" font-family="sans-serif" font-size="14" fill="#333">How does AIVA remember our conversation?</text>
            <circle cx="100" cy="100" r="30" fill="#00bfff" />
            <circle cx="90" cy="90" r="4" fill="#00bfff" />
            <circle cx="110" cy="90" r="4" fill="#00bfff" />
            <circle cx="100" cy="110" r="4" fill="#00bfff" />
            <text x="60" y="120" font-family="sans-serif" font-size="10" fill="white">Console</text>
            <circle cx="700" cy="350" r="30" fill="#ff9999" />
            <text x="710" y="360" font-family="sans-serif" font-size="10" fill="#333">You</text>
          `;
        } else if (state.step === 1) {
          envelope.style.opacity = '1';
          grace.style.opacity = '0';
          textBubble.style.opacity = '0';
          graceText.style.opacity = '0';
          svg.appendChild(envelope);
        } else if (state.step === 2) {
          envelope.style.opacity = '1';
          grace.style.opacity = '0';
          textBubble.style.opacity = '0';
          graceText.style.opacity = '0';
          svg.appendChild(envelope);
        } else if (state.step === 3) {
          envelope.style.opacity = '0';
          grace.style.opacity = '1';
          textBubble.style.opacity = '1';
          graceText.style.opacity = '0.8';
          svg.appendChild(grace);
          svg.appendChild(textBubble);
          svg.appendChild(graceText);
        } else if (state.step === 4) {
          envelope.style.opacity = '0';
          grace.style.opacity = '1';
          textBubble.style.opacity = '1';
          graceText.style.opacity = '1';
          svg.appendChild(grace);
          svg.appendChild(textBubble);
          svg.appendChild(graceText);
        } else if (state.step === 5) {
          envelope.style.opacity = '0';
          grace.style.opacity = '1';
          textBubble.style.opacity = '1';
          graceText.style.opacity = '1';
          svg.appendChild(grace);
          svg.appendChild(textBubble);
          svg.appendChild(graceText);
        } else if (state.step === 6) {
          envelope.style.opacity = '0';
          grace.style.opacity = '1';
          textBubble.style.opacity = '1';
          graceText.style.opacity = '1';
          svg.appendChild(grace);
          svg.appendChild(textBubble);
          svg.appendChild(graceText);
        }
      }

      // Step labels
      const stepLabels = [
        "Composing a message in the Console",
        "Encoding and sending the request",
        "Decoding at the telepathy receptor",
        "Interactive assembling the response",
        "Nymphaea RP processing the request",
        "Streaming the response back",
        "Memory saving the exchange"
      ];

      // Control functions
      function reset() {
        state.step = 0;
        state.playing = false;
        clearInterval(state.interval);
        updateSVG();
        updateControls();
        stepLabel.textContent = stepLabels[state.step];
      }

      function next() {
        if (state.step < 6) {
          state.step++;
          updateSVG();
          updateControls();
          stepLabel.textContent = stepLabels[state.step];
        }
      }

      function togglePlay() {
        if (state.playing) {
          clearInterval(state.interval);
          state.playing = false;
          playButton.textContent = 'Play';
        } else {
          if (state.step < 6) {
            state.playing = true;
            state.interval = setInterval(() => {
              next();
              if (state.step === 6) {
                clearInterval(state.interval);
                state.playing = false;
                playButton.textContent = 'Play';
              }
            }, 1500);
            playButton.textContent = 'Pause';
          }
        }
      }

      function updateControls() {
        nextButton.disabled = state.step === 6;
        if (state.playing) {
          nextButton.disabled = true;
        }
      }

      // Event listeners
      resetButton.addEventListener('click', reset);
      nextButton.addEventListener('click', next);
      playButton.addEventListener('click', togglePlay);

      // Initialize
      updateSVG();
      updateControls();

      // Expose API
      window.AIVA_DEMO = {
        reset: reset,
        next: next,
        togglePlay: togglePlay,
        getState: () => ({ step: state.step, playing: state.playing })
      };
    </script>
  </body>
</html>
